IOCIOC是一种思想，全称叫做Inversion of Control，控制反转，意思是如果有两个对象A依赖于B，把本来A运行时需要主动创建B对象的操作交给IOC容器来帮我们做，创建B对象并注入A，实现了解耦
IOC也可以叫做DI，Dependency Injection，依赖注入，或者说DI是IOC思想的具体实现方式
AOP定义AOP, (Aspect Orient Programming)，面向切面编程，拦截指定方法并对方法进行增强，不修改源代码的情况下给程序动态添加额外功能

横切关注点（cross-cutting concerns）：多个类或对象中的公共行为（如日志记录、事务管理、权限控制、接口限流、接口幂等等）。

切面（Aspect）：对横切关注点进行封装的类，实现具体的功能。（切面 &#x3D; 切入点 + 通知，通俗点就是在什么时机，什么地方，做什么增强）

连接点（JoinPoint）：方法调用或方法执行的某个时刻。（能够被拦截的地方，Spring AOP 是基于动态代理的，所以是方法拦截的，每个成员方法都可以称之为连接点）

通知（Advice）：切面在某个连接点要执行的操作，有Before，After，AfterReturning，AfterThrowing，Around。在方法执行的什么时机（when：方法前&#x2F;方法后&#x2F;方法前后）做什么（what：增强的功能）

切点（Pointcut）：一个表达式，用来匹配哪些连接点需要被切面增强。（在哪些类，哪些方法上切入（where））

织入（weaving）：把切面加入到对象，并创建出代理对象的过程，这个由 Spring 来完成。


实现AOP可以通过动态代理或操作字节码实现
对于接口类型的对象，Spring 会使用 JDK 动态代理。JDK 动态代理通过实现与目标对象相同的接口，在代理对象的方法调用前后插入切面逻辑（如日志记录的代码）。对于没有实现接口的类，Spring 会使用 CGLIB（Code Generation Library）动态代理，CGLIB 通过继承目标类并覆盖目标类的方法来实现代理，在覆盖的方法中插入切面逻辑。
AOP实例公共字段自动填充利用AOP实现对数据的一些公共字段如createTime，updateUser等的自动填充功能，无需再手动set
自定义注解
/** * 自定义注解，用于标识某个方法需要进行公共字段的自动填充 */@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)public @interface AutoFill &#123;    //数据库操作类型： UPDATE, INSERT    OperationType value();&#125;//枚举定义数据库操作public enum OperationType &#123;    UPDATE,//更新操作    INSERT//插入操作&#125;



要被填充的方法
以DishMapper举例
/** * 新增菜品 * @param dish */@AutoFill(OperationType.INSERT)void insert(Dish dish);



切面类
实现具体的填充功能
@Aspect //标注这是一个切面类@Component //加入Spring容器public class AutoFillAspect &#123;    //切点    @Pointcut(&quot;execution(* com.sky.map	per.*.*(..)) &amp;&amp; @annotation(com.sky.annotation.AutoFill)&quot;)    public void autoFillPointCut() &#123;&#125;    //通知    @Before(&quot;autoFillPointCut()&quot;)//方法调用前执行autoFill方法，    public void autoFill(JoinPoint joinPoint) &#123; // JoinPoint：连接点        //获取操作类型        MethodSignature signature = (MethodSignature) joinPoint.getSignature();//获取方法签名        AutoFill autoFill = signature.getMethod().getAnnotation(AutoFill.class);//方法上的注解对象        OperationType type = autoFill.value();//数据库操作类型        //获取切入点方法的参数列表        Object[] args = joinPoint.getArgs();        if (args == null || args.length == 0) &#123;            return;        &#125;        Object entity = args[0]; // 这里就是Dish实体类        //准备赋值的数据        LocalDateTime now = LocalDateTime.now();        Long currentId = BaseContext.getCurrentId();        //根据操作类型，通过反射为对应的属性赋值        if (type == OperationType.INSERT) &#123;            try &#123;                Method setCreatTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_CREATE_TIME,                        LocalDateTime.class);                Method setUpdateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_TIME,                        LocalDateTime.class);                Method setUpdateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_USER,                        Long.class);                Method setCreateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_CREATE_USER,                        Long.class);                setCreateUser.invoke(entity, currentId);                setUpdateUser.invoke(entity, currentId);                setUpdateTime.invoke(entity, now);                setCreatTime.invoke(entity, now);            &#125; catch (Exception e) &#123;                throw new RuntimeException(e);            &#125;        &#125; else if (type == OperationType.UPDATE) &#123;            try &#123;                Method setUpdateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_TIME,                        LocalDateTime.class);                Method setUpdateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_USER,                        Long.class);                setUpdateUser.invoke(entity, currentId);                setUpdateTime.invoke(entity, now);            &#125; catch (Exception e) &#123;                throw new RuntimeException(e);            &#125;        &#125;    &#125;&#125;

日志记录定义日志记录切面记录Controller中方法的运行细节
/** * 自定义日志注解 * @author Fu1sh */@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)@Documentedpublic @interface Logger &#123;    String description() default &quot;&quot;;&#125;

@Configuration@Aspect@Slf4j@ConditionalOnClass(DispatcherServlet.class)public class LoggerAspect &#123;    //*：匹配任意返回值的方法     //com.hmall..controller：匹配包    //.*.*(..)：匹配包下任意类、任意方法、任意方法参数    @Pointcut(&quot;execution(* com.hmall..controller.*.*(..)) &amp;&amp; @annotation(com.hmall.common.annotation.Logger)&quot;)    public void loggerPointCut() &#123;&#125;    @Around(&quot;loggerPointCut()&quot;)    public Object loggerAround(ProceedingJoinPoint joinPoint) &#123;        HttpServletRequest request = getRequest();        WebLog webLog;        Object result = null;        try &#123;            log.info(&quot;================前置通知===============&quot;);            long start = System.currentTimeMillis();            //执行拦截的方法            result = joinPoint.proceed();            log.info(&quot;================返回通知===============&quot;);            long l = System.currentTimeMillis() - start;            long timeCost = TimeUnit.SECONDS.toSeconds(l);            Logger logger = getAnnotationLogger(joinPoint);            webLog = WebLog.builder() //WebLog封装了将要展示的日志信息                    .description(logger.description())                    .startTime(start)                    .timeCost(timeCost)                    .url(request.getRequestURL().toString())                    .uri(request.getRequestURI())                    .ipAddress(request.getRemoteAddr())                    .params(getParams(joinPoint))                    .result(result)                    .build();            log.info(webLog.toString());        &#125; catch (Throwable e) &#123;            log.info(&quot;================异常通知===============&quot;);            log.error(e.getMessage(), e);        &#125; finally &#123;            log.info(&quot;================后置通知===============&quot;);        &#125;        return result;    &#125;    private Object getParams(ProceedingJoinPoint joinPoint) &#123;        MethodSignature methodSignature = getMethodSignature(joinPoint);        String[] parameterNames = methodSignature.getParameterNames();        Object[] parameterValues = joinPoint.getArgs();        Map&lt;String, Object&gt; params = new HashMap&lt;&gt;();        for (int i = 0; i &lt; parameterNames.length; i++) &#123;            params.put(parameterNames[i], parameterValues[i]);        &#125;        return params;    &#125;    private Logger getAnnotationLogger(ProceedingJoinPoint joinPoint) &#123;        return getMethodSignature(joinPoint).getMethod().getAnnotation(Logger.class);    &#125;    private static MethodSignature getMethodSignature(ProceedingJoinPoint joinPoint) &#123;        return (MethodSignature) joinPoint.getSignature();    &#125;    /**     * 获取http请求对象     * @return     */    private HttpServletRequest getRequest() &#123;        ServletRequestAttributes requestAttributes = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();        return requestAttributes != null ? requestAttributes.getRequest() : null;    &#125;&#125;

@ApiOperation(&quot;用户登录接口&quot;)@PostMapping(&quot;login&quot;)@Logger(description = &quot;登录&quot;) //使用自定义日志注解记录日志信息public UserLoginVO login(@RequestBody @Validated LoginFormDTO loginFormDTO)&#123;    return userService.login(loginFormDTO);&#125;


RequestContextHolder是Spring 提供的工具类，它使用ThreadLocal存储当前请求的上下文信息，主要用途是从任意位置获取当前 ServletRequest 和其他请求相关的信息，特别是在不直接处理请求的组件（如 @Service 或 @Component）中。

AOP失效场景自调用AOP 基于代理机制来工作，当一个类的方法在同一个类内部被另一个方法调用时，这种自调用是直接调用的，不会经过代理对象，从而导致切面失效。
目标类未被 Spring 管理AOP 依赖于 Spring 管理的 Bean，如果目标类不是由 Spring 容器管理的 Bean，则切面不会生效。如果一个类通过 new 操作符实例化，而不是通过 Spring 容器注入，那么 AOP 不会生效，因为 Spring 不能为其创建代理对象。
final关键字final修饰的类不能被继承，修饰的方法不能被重写。
JDK 动态代理：JDK 动态代理只能代理接口中的方法，而不涉及类的继承，因此 final 类和 final 方法的限制对 JDK 动态代理没有直接影响。但由于 JDK 动态代理只能代理接口方法，所以如果类没有实现接口，Spring 会默认使用 CGLIB 代理。
CGLIB 代理：CGLIB 代理通过生成目标类的子类并重写方法来实现代理。如果类或方法是 final 的，CGLIB 代理就无法创建有效的代理对象，因为它无法继承 final 类或重写 final 方法，这会导致 AOP 切面失效。
private方法同理Spring AOP 仅支持公共方法（public）的切面，对于 private、protected 和 package-private 方法，切面不会生效。
@Transactionalprivate void privateMethod() &#123;    // 事务逻辑不会生效，因为方法是私有的，无法被重写&#125;

在使用Dubbo调用服务时出现了异常:
Fail to decode request due to: RpcInvocation [methodName=queryItemByIds, parameterTypes=null]

服务提供方也报错：
org.apache.dubbo.common.serialize.SerializationException: com.alibaba.fastjson2.JSONException: create instance error interface java.util.Set, offset 7

调用该服务的代码：
Map&lt;Long, Integer&gt; itemNumMap = detailDTOS.stream()        .collect(Collectors.toMap(OrderDetailDTO::getItemId, OrderDetailDTO::getNum));Set&lt;Long&gt; itemIds = itemNumMap.keySet();//查询商品List&lt;ItemDTO&gt; items = itemService.queryItemByIds(itemIds);

而另一个消费者调用该服务是正常的：
Set&lt;Long&gt; itemIds = vos.stream().map(CartVO::getItemId).collect(Collectors.toSet());//查询商品List&lt;ItemDTO&gt; items = itemService.queryItemByIds(itemIds);

对比了一下应该是传入参数Set的类型不一致导致的异常，失败的调用传入的参数是keySet，只是Map的一个集合视图，无法被Dubbo序列化和反序列化，修改为HashSet后就可以成功调用了：
Set&lt;Long&gt; itemIds = new HashSet&lt;&gt;(itemNumMap.keySet());

什么是网关网关-网络的关口，门卫。数据从一个网络传输到另一个网络需要经过网关来做数据的路由和转发，以及数据安全的校验工作。从此以后，前端请求不再直接访问后端服务，而是访问网关（也是一个微服务）。

路由：选择数据要去的服务的目的地址
转发：转发数据给对应的服务
校验：在网关层面进行数据鉴权


SpringCloud提供了两种网关实现：

Netflix Zuul：早期实现，目前已经淘汰
SpringCloudGateway：基于Spring的WebFlux技术，完全支持响应式编程，吞吐能力更强


响应式编程模型，即通过异步和非阻塞的方式处理数据流和事件。

依赖&lt;!--网关--&gt;&lt;dependency&gt;    &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt;    &lt;artifactId&gt;spring-cloud-starter-gateway&lt;/artifactId&gt;&lt;/dependency&gt;&lt;!--负载均衡--&gt;&lt;dependency&gt;    &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt;    &lt;artifactId&gt;spring-cloud-starter-loadbalancer&lt;/artifactId&gt;&lt;/dependency&gt;

配置gateway:  routes: #路由    - id: item-service  #路由唯一标识      uri: lb://item-service  #路由目标地址      predicates: #断言，判断请求是否符合当前路由        - Path=/items/**,/search/**    - id: cart-service      uri: lb://cart-service      predicates:        - Path=/carts/**  default-filters: #过滤器，也可以添加在每一个路由中	- AddRequestParameter=red, blue 

// 过滤器执行示意@ApiOperation(&quot;分页查询商品&quot;)@GetMapping(&quot;/page&quot;)public PageDTO&lt;ItemDTO&gt; queryItemByPage(PageQuery query, @RequestParam(&quot;red&quot;) String res) &#123;    System.out.println(res); //输出blue

JWT校验流程
用户登录后，用户微服务user-service使用预定义的jwt秘钥为用户生成一个JWT令牌（token），返回给客户端
用户之后对任何微服务的请求都必须带上这个token，服务端校验token（为空、篡改、过期等），成功后才执行请求的方法，返回数据。

使用网关进行登录校验每个微服务都实现JWT校验逻辑未免太过复杂，而我们的网关正好会对所有的请求路由和转发，在网关层进行JWT校验在合适不过。
不过，这里存在几个问题：

网关路由是配置的，请求转发是Gateway内部代码，我们如何在转发之前做登录校验？

– 网关过滤器


网关校验JWT之后，如何将用户信息传递给微服务？

– SpringMVC拦截器拦截网关转发的所有http请求，将用户信息保存到ThreadLocal中


微服务之间也会相互调用，这种调用不经过网关，又该如何传递用户信息？ 

– OpenFeign请求拦截器，一个微服务在通过Feign调用另一个微服务时，发起http请求之前先从ThreadLocal中拿到userId，将userId作为请求头加入http请求，再发送请求到另一个微服务



//网关过滤器@Component@RequiredArgsConstructor@EnableConfigurationProperties(AuthProperties.class)public class AuthFilter implements GlobalFilter, Ordered &#123;    private final JwtTool jwtTool;    private final AuthProperties authProperties;    private final AntPathMatcher antPathMatcher = new AntPathMatcher();// Spring 框架提供的路径模式匹配器    @Override    public Mono&lt;Void&gt; filter(ServerWebExchange exchange, GatewayFilterChain chain) &#123;        //1.get request        ServerHttpRequest request = exchange.getRequest();        //1.1 check request path to see if it needs a login interception        RequestPath path = request.getPath();        if (pathIsExclude(path)) &#123;            return chain.filter(exchange);        &#125;        //2.get token from header        //3.verify token, check if user has login        String token = null;        List&lt;String&gt; headers = request.getHeaders().get(&quot;authorization&quot;);        if (headers != null &amp;&amp; !headers.isEmpty()) &#123;            token = headers.get(0);        &#125;        //4.do jwt verifying        Long userId;        try &#123;            userId = jwtTool.parseToken(token); //校验token逻辑        &#125; catch (UnauthorizedException e) &#123;            //Unauthorized!            ServerHttpResponse response = exchange.getResponse();            response.setStatusCode(HttpStatus.UNAUTHORIZED);            return response.setComplete(); //return 401        &#125;        //5.pass userinfo to next filter        ServerWebExchange swe = exchange.mutate().request(builder -&gt;                builder.header(&quot;user-id&quot;, userId.toString())).build();        return chain.filter(swe);    &#125;    /**     * 判断路径是否合法     * @param path     * @return     */    private boolean pathIsExclude(RequestPath path) &#123;        List&lt;String&gt; excludePaths = authProperties.getExcludePaths();        for (String pathPatten : excludePaths) &#123;            if (antPathMatcher.match(pathPatten, String.valueOf(path))) &#123;                return true;            &#125;        &#125;        return false;    &#125;    /**     * 定义Filter的优先级，需要低于NettyRoutingFilter的优先级Integer.MAX_VALUE     * @return     */    @Override    public int getOrder() &#123;        return 0;    &#125;&#125;

//SpringMVC拦截器@Componentpublic class AuthInterceptor implements HandlerInterceptor &#123;@Overridepublic boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception &#123;    String userId = request.getHeader(&quot;user-id&quot;);    if (StrUtil.isNotBlank(userId)) &#123; //有些路径是不需要登录拦截的：/search /users/login /items                                        //因此不会有user-id这个请求头，所以必须判断非空        UserContext.setUser(Long.valueOf(userId));    &#125;    return true; //放行&#125;@Overridepublic void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) throws Exception &#123;    UserContext.removeUser();&#125;

//OpenFeign请求拦截器@BeanRequestInterceptor feignRequestInterceptor() &#123;    return requestTemplate -&gt; &#123;        Long userId = UserContext.getUser();        if (userId != null) &#123;            requestTemplate.header(&quot;user-id&quot;, userId.toString());        &#125;    &#125;;&#125;

HashMap源码分析虽然在学习CS61B的时候自己动手写了一个简易版的HashMap，但是跟实际的完全没有可比性，最近开始深入底层，遂记录。
初始参数static final int DEFAULT_INITIAL_CAPACITY = 1 &lt;&lt; 4; // aka 16static final int MAXIMUM_CAPACITY = 1 &lt;&lt; 30;static final float DEFAULT_LOAD_FACTOR = 0.75f;static final int TREEIFY_THRESHOLD = 8;//转红黑树阈值，链表中元素大于此就将其转为红黑树static final int UNTREEIFY_THRESHOLD = 6; //树转链表阈值，树中元素低于此就转为链表static final int MIN_TREEIFY_CAPACITY = 64; //整个表中元素超过该值时才可以开启树形化操作 ？？？？还是数组长度？？？



初始方法// &gt;&gt;&gt;表示无符号右移// 对key的hashCode右移16位再异或，可以增加hash的复杂度，降低hash冲突的概率static final int hash(Object key) &#123;	int h;    return (key == null) ? 0 : (h = key.hashCode()) ^ (h &gt;&gt;&gt; 16);    //注意这里允许key为null！！！为null的hashcode就是0，相当于只能有一个key为null&#125;

putpublic V put(K key, V value) &#123;	return putVal(hash(key), key, value, false, true);&#125;/*** onlyIfAbsent:默认为false，表示若key相同，用新值覆盖旧值**/final V putVal(int hash, K key, V value, boolean onlyIfAbsent,                   boolean evict) &#123;        Node&lt;K,V&gt;[] tab; Node&lt;K,V&gt; p; int n, i;    	//第一次插入元素，初始化，HashMap为了节约内存在使用时才初始化数组        if ((tab = table) == null || (n = tab.length) == 0)            n = (tab = resize()).length;    	//路由地址算法，即hash % n，这里n为数组长度，始终是2的幂，故可以用位运算来优化    	//数组该地址对应的节点为空，创建一个新节点即可        if ((p = tab[i = (n - 1) &amp; hash]) == null)            tab[i] = newNode(hash, key, value, null);        else &#123;            Node&lt;K,V&gt; e; K k;            //当前节点就是目标节点            if (p.hash == hash &amp;&amp;                ((k = p.key) == key || (key != null &amp;&amp; key.equals(k))))                e = p;            //没找到目标节点，且当前节点是红黑树节点            else if (p instanceof TreeNode)                e = ((TreeNode&lt;K,V&gt;)p).putTreeVal(this, tab, hash, key, value);            //当前节点是普通链表节点            else &#123;                for (int binCount = 0; ; ++binCount) &#123;                    //尾插法                    if ((e = p.next) == null) &#123;                        p.next = newNode(hash, key, value, null);                        if (binCount &gt;= TREEIFY_THRESHOLD - 1) // -1 for 1st                            treeifyBin(tab, hash);                        break;                    &#125;                    //找到目标节点，立即break;                    if (e.hash == hash &amp;&amp;                        ((k = e.key) == key || (key != null &amp;&amp; key.equals(k))))                        break;                    p = e;                &#125;            &#125;	            //存在key对应的mapping            if (e != null) &#123; // existing mapping for key                V oldValue = e.value;                // 覆盖旧值                if (!onlyIfAbsent || oldValue == null)                    e.value = value;                afterNodeAccess(e);                return oldValue;            &#125;        &#125;        ++modCount;        if (++size &gt; threshold)            resize();        afterNodeInsertion(evict);        return null;    &#125;



resize/** * newCap: the new capacity, MUST be a power of two */final Node&lt;K,V&gt;[] resize() &#123;    Node&lt;K,V&gt;[] oldTab = table;   // 获取旧表    int oldCap = (oldTab == null) ? 0 : oldTab.length;  // 获取旧表的容量old capacity    int oldThr = threshold;  // 获取旧的扩容阈值    int newCap, newThr = 0;    if (oldCap &gt; 0) &#123;  // 如果旧表的容量大于0        if (oldCap &gt;= MAXIMUM_CAPACITY) &#123;  // 如果旧容量已经达到最大容量            threshold = Integer.MAX_VALUE;  // 将阈值设置为最大值            return oldTab;  // 返回旧表        &#125;        newCap = oldCap &lt;&lt; 1;  // 新容量是旧容量的两倍        if (newCap &lt; MAXIMUM_CAPACITY &amp;&amp; oldCap &gt;= DEFAULT_INITIAL_CAPACITY)            newThr = oldThr &lt;&lt; 1;  // 新的扩容阈值也是旧阈值的两倍    &#125;    else if (oldThr &gt; 0) // initial capacity was placed in threshold        newCap = oldThr;  // 如果旧容量为0但旧阈值大于0，设置新容量为旧阈值    else &#123;               // oldThr == 0 &amp;&amp; oldCap == 0 此为第一次初始化map时的操作        newCap = DEFAULT_INITIAL_CAPACITY;  // 设置新容量为默认初始容量        newThr = (int)(DEFAULT_LOAD_FACTOR * DEFAULT_INITIAL_CAPACITY);  // 设置新的扩容阈值 16 * 0.75 = 12    &#125;    if (newThr == 0) &#123;        float ft = (float)newCap * loadFactor;        newThr = (newCap &lt; MAXIMUM_CAPACITY &amp;&amp; ft &lt; (float)MAXIMUM_CAPACITY ?                  (int)ft : Integer.MAX_VALUE);    &#125;    threshold = newThr;  // 更新阈值    @SuppressWarnings(&#123;&quot;rawtypes&quot;,&quot;unchecked&quot;&#125;)    Node&lt;K,V&gt;[] newTab = (Node&lt;K,V&gt;[])new Node[newCap];  // 创建新表    table = newTab;    if (oldTab != null) &#123;  // 如果旧表不为空        for (int j = 0; j &lt; oldCap; ++j) &#123;  // 遍历旧表中的每个桶            Node&lt;K,V&gt; e;            if ((e = oldTab[j]) != null) &#123;  // 如果当前桶不为空                oldTab[j] = null;  // 释放旧表中的引用，帮助垃圾回收                if (e.next == null)  // 如果当前桶中只有一个节点                    newTab[e.hash &amp; (newCap - 1)] = e;  // 直接将节点放到新表中的相应位置                else if (e instanceof TreeNode)  // 如果当前桶是树节点                    ((TreeNode&lt;K,V&gt;)