import java.io.Serializable;public class FredMap&lt;K, V&gt; implements Serializable &#123;    static class Node&lt;K, V&gt; implements Serializable&#123;        final K key;        V value;        Node&lt;K, V&gt; next;        Node(K key, V value, Node&lt;K, V&gt; next) &#123;            this.key = key;            this.value = value;            this.next = next;        &#125;    &#125;    private static final float LOAD_FACTOR = 0.75F;    private static final int INIT_CAPACITY = 1 &lt;&lt; 4;    private int size;    private Node&lt;K, V&gt;[] table;    public FredMap() &#123;    &#125;    private static int hash(Object key) &#123;        int h;        return key == null ? 0 : (h = key.hashCode()) ^ (h &gt;&gt;&gt; 16);    &#125;    public V put(K key, V value) &#123;        if (table == null) &#123;            table = new Node[INIT_CAPACITY];        &#125;        int hash = hash(key);        Node&lt;K, V&gt; node = table[hash];        while (node != null) &#123;            if (node.key.equals(key)) &#123;//若存在重复key                V oldValue = node.value;                node.value = value;                return oldValue;            &#125;            node = node.next;        &#125;        table[hash] = new Node&lt;K, V&gt;(key, value, table[hash]);//头插法        size += 1;        if (size &gt; LOAD_FACTOR * table.length) &#123;            resize();        &#125;        return null;    &#125;    private void resize() &#123;        int newCapacity = table.length * 2;        Node&lt;K, V&gt;[] oldTable = table;        table = new Node[newCapacity];        size = 0;        for (Node&lt;K, V&gt; node : oldTable) &#123;            while (node != null) &#123;                put(node.key, node.value);                node = node.next;            &#125;        &#125;    &#125;    public V get(K key) &#123;        int hash = hash(key);        Node&lt;K, V&gt; node = table[hash];        while (node != null) &#123;            if (node.key.equals(key)) &#123;                return node.value;            &#125;            node = node.next;        &#125;        return null;    &#125;    public V remove(K key) &#123;        int hash = hash(key);        Node&lt;K, V&gt; node = table[hash];        Node&lt;K, V&gt; prev = null;        while (node != null) &#123;            if (node.key.equals(key)) &#123;                V returnValue =  node.value;                if (prev == null) &#123;                    table[hash] = node.next;                &#125; else &#123;                    prev.next = node.next;                &#125;                size -= 1;                return returnValue;            &#125;            prev = node;            node = node.next;        &#125;        return null;    &#125;    public int size() &#123;        return size;    &#125;    public boolean isEmpty() &#123;        return size == 0;    &#125;&#125;

