// Invariants: mark &lt;= position &lt;= limit &lt;= capacityprivate int mark = -1; //调用mark()方法标记position位置，以便之后resetprivate int position = 0; //下一个操作的位置private int limit; //position能到的最大位置，默认是capacityprivate int capacity;//Allocates a new int buffer.public static IntBuffer allocate(int capacity) &#123;    if (capacity &lt; 0)        throw createCapacityException(capacity);    return new HeapIntBuffer(capacity, capacity, null); //返回一个堆缓冲区&#125;//Wraps an int array into a buffer.public static IntBuffer wrap(int[] array, int offset, int length)&#123;    try &#123;        return new HeapIntBuffer(array, offset, length, null);    &#125; catch (IllegalArgumentException x) &#123;        throw new IndexOutOfBoundsException();    &#125;&#125;


