public IntBuffer put(int x) &#123;    hb[ix(nextPutIndex())] = x; //hb数组position位置赋值为x    return this;&#125;final int nextPutIndex() &#123;                          // package-private    int p = position;    if (p &gt;= limit)        throw new BufferOverflowException();    position = p + 1; //position加一    return p;&#125;


