selector一个组件，可以检测多个NIO channel，看看读或者写事件是否就绪。
多个Channel以事件的方式可以注册到同一个Selector，从而达到用一个线程处理多个请求成为可能。
//服务端//ServerSocketChannel 用于服务端，负责监听和接受连接请求。//SocketChannel 用于客户端或服务端，负责连接和进行数据传输。try (ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();     Selector selector = Selector.open()) &#123;    serverSocketChannel.bind(new InetSocketAddress(9999));    //要使用选择器，必须使用非阻塞方式，这样才不会像阻塞IO一样卡在accept()方法    serverSocketChannel.configureBlocking(false);    serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);    while (true) &#123;        int count = selector.select();        System.out.println(&quot;监听到&quot;+ count +&quot;个事件&quot;);        Set&lt;SelectionKey&gt; selectionKeys = selector.selectedKeys();        Iterator&lt;SelectionKey&gt; iterator = selectionKeys.iterator();        while (iterator.hasNext()) &#123;            SelectionKey key = iterator.next();            if (key.isAcceptable()) &#123; //如果当前key对应的通道已经做好准备accept                SocketChannel socketChannel = serverSocketChannel.accept();                System.out.println(&quot;客户端连接：&quot; + socketChannel.getRemoteAddress());                //将这个连接也注册到选择器                socketChannel.configureBlocking(false);                socketChannel.register(selector, SelectionKey.OP_READ);            &#125; else if (key.isReadable()) &#123; //如果当前连接有可读的数据并且可以写，就开始处理                SocketChannel socketChannel = (SocketChannel) key.channel();                ByteBuffer byteBuffer = ByteBuffer.allocate(1024);                int read = socketChannel.read(byteBuffer);                if (read &gt; 0) &#123;                    byteBuffer.flip();                    System.out.println(new String(byteBuffer.array(), 0, read));                &#125;                socketChannel.write(ByteBuffer.wrap(&quot;已收到&quot;.getBytes()));            &#125;            iterator.remove();//调用 iterator.remove() 是为了从 selectedKeys 集合中移除已经处理过的 SelectionKey。如果不移除，下一次循环时这些 SelectionKey 还会被再次处理，可能会导致重复处理同一个事件。        &#125;    &#125;&#125; catch (IOException e) &#123;    throw new RuntimeException(e);&#125;//客户端try (SocketChannel socketChannel =     SocketChannel.open(new InetSocketAddress(&quot;127.0.0.1&quot;, 9999));     Scanner scanner = new Scanner(System.in)) &#123;    System.out.println(&quot;已连接服务器！&quot;);    while (true) &#123;        System.out.println(&quot;请输入发送的内容：&quot;);        String line = scanner.nextLine();        socketChannel.write(ByteBuffer.wrap(line.getBytes()));        ByteBuffer buffer = ByteBuffer.allocate(1024);        socketChannel.read(buffer);        buffer.flip();        System.out.println(&quot;收到服务器返回的：&quot;+ new String(buffer.array(), 0, buffer.limit()));    &#125;&#125; catch (IOException e) &#123;    throw new RuntimeException(e);&#125;



reactor模式//Reactor，统筹全局public class Reactor implements Runnable, Closeable &#123;    private final ServerSocketChannel serverSocketChannel;    private final Selector selector;    public Reactor() throws IOException &#123;        this.serverSocketChannel = ServerSocketChannel.open();        this.selector = Selector.open();    &#125;    @Override    public void run() &#123;        try &#123;            serverSocketChannel.bind(new InetSocketAddress(9999));            //要使用选择器，必须使用非阻塞方式，这样才不会像阻塞IO一样卡在accept()方法            serverSocketChannel.configureBlocking(false);            serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT, new Acceptor(serverSocketChannel, selector));            while (true) &#123;                int count = selector.select();                System.out.println(&quot;监听到&quot; + count + &quot;个事件&quot;);                Set&lt;SelectionKey&gt; selectionKeys = selector.selectedKeys();                Iterator&lt;SelectionKey&gt; iterator = selectionKeys.iterator();                while (iterator.hasNext()) &#123;                    this.dispatch(iterator.next());//SelectionKey实际上就是Acceptor或者Handler，这里转发过去调用run方法启动。                    iterator.remove();                &#125;            &#125;        &#125; catch (IOException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    private void dispatch (SelectionKey key) &#123;        Object attachment = key.attachment();        if (attachment instanceof Runnable) &#123;            ((Runnable) attachment).run();        &#125;    &#125;    @Override    public void close() throws IOException &#123;        serverSocketChannel.close();        selector.close();    &#125;&#125;//Acceptor 负责监听和接收连接请求public class Acceptor implements Runnable &#123;    private final ServerSocketChannel serverSocketChannel;    private final Selector selector;    public Acceptor(ServerSocketChannel serverSocketChannel, Selector selector) &#123;        this.serverSocketChannel = serverSocketChannel;        this.selector = selector;    &#125;    @Override    public void run() &#123;        try &#123;            SocketChannel socketChannel = serverSocketChannel.accept();            System.out.println(&quot;客户端连接：&quot; + socketChannel.getRemoteAddress());            //将这个连接也注册到选择器            socketChannel.configureBlocking(false);            socketChannel.register(selector, SelectionKey.OP_READ, new Handler(socketChannel));        &#125; catch (IOException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;&#125;//Handler 处理每个客户端连接的任务public class Handler implements Runnable&#123;    private final SocketChannel socketChannel;    private final ThreadPoolExecutor pool;    public Handler(SocketChannel socketChannel) &#123;        this.socketChannel = socketChannel;        pool = new ThreadPoolExecutor(5, 20,                60, TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(),                new ThreadPoolExecutor.CallerRunsPolicy());    &#125;    @Override    public void run() &#123;        try &#123;            ByteBuffer byteBuffer = ByteBuffer.allocate(20);            int read = socketChannel.read(byteBuffer);            if (read &lt; 0) &#123;                socketChannel.close();                System.out.println(&quot;客户端断开连接！&quot;);                return;            &#125;            pool.execute(() -&gt; &#123;                try &#123;                    if (byteBuffer.remaining() == 0) &#123;                        byteBuffer.flip();                        System.out.println(&quot;线程 &quot;+ Thread.currentThread().getName() + &quot; &quot; +                                &quot;处理客户端消息： &quot; + new String(byteBuffer.array(), 0, byteBuffer.remaining()));                        byteBuffer.clear();                    &#125;                    socketChannel.write(ByteBuffer.wrap(&quot;已收到&quot;.getBytes()));                &#125; catch (IOException e) &#123;                    throw new RuntimeException(e);                &#125; 