class Solution &#123;    List&lt;List&lt;String&gt;&gt; res = new LinkedList&lt;&gt;();     LinkedList&lt;String&gt; path = new LinkedList&lt;&gt;();     public List&lt;List&lt;String&gt;&gt; partition(String s) &#123;        dfs(s, 0);        return res;    &#125;    private void dfs(String s, int i) &#123;        int n = s.length();        if (i == n) &#123;            res.add(new LinkedList&lt;&gt;(path));            return;        &#125;        for (int j = i; j &lt; n; ++ j) &#123;//枚举选哪个，答案的视角，每个位置必须填入一个字符            String t = s.substring(i, j + 1);            if (isH(t)) &#123;                path.add(t);                dfs(s, j + 1);                path.removeLast();            &#125;        &#125;    &#125;    private boolean isH(String s) &#123;        int l = 0, r = s.length() - 1;        while (l &lt; r) &#123;            if (s.charAt(l) != s.charAt(r)) &#123;                return false;            &#125;            l ++; r --;        &#125;        return true;    &#125;&#125;

class Solution &#123;    List&lt;List&lt;String&gt;&gt; res = new LinkedList&lt;&gt;();     LinkedList&lt;String&gt; path = new LinkedList&lt;&gt;();     public List&lt;List&lt;String&gt;&gt; partition(String s) &#123;        dfs(s, 0, 0);        return res;    &#125;    private void dfs(String s, int i, int start) &#123;        int n = s.length();        if (i == n) &#123;            res.add(new LinkedList&lt;&gt;(path));            return;        &#125;        if (i &lt; n - 1) &#123;//选或者不选第i和i+1个字符中间的逗号            dfs(s, i + 1, start);        &#125;        String t = s.substring(start, i + 1);        if (isH(t)) &#123;            path.add(t);            dfs(s, i + 1, i + 1);            path.removeLast();        &#125;    &#125;    private boolean isH(String s) &#123;        int l = 0, r = s.length() - 1;        while (l &lt; r) &#123;            if (s.charAt(l) != s.charAt(r)) &#123;                return false;            &#125;            l ++; r --;        &#125;        return true;    &#125;&#125;

93. 复原 IP 地址有效 IP 地址 正好由四个整数（每个整数位于 0 到 255 之间组成，且不能含有前导 0），整数之间用 &#39;.&#39; 分隔。

例如：&quot;0.1.2.201&quot; 和 &quot;192.168.1.1&quot; 是 有效 IP 地址，但是 &quot;0.011.255.245&quot;、&quot;192.168.1.312&quot; 和 &quot;192.168@1.1&quot; 是 无效 IP 地址。

给定一个只包含数字的字符串 s ，用以表示一个 IP 地址，返回所有可能的有效 IP 地址，这些地址可以通过在 s 中插入 &#39;.&#39; 来形成。你 不能 重新排序或删除 s 中的任何数字。你可以按 任何 顺序返回答案。
示例 1：
输入：s = &quot;25525511135&quot;输出：[&quot;255.255.11.135&quot;,&quot;255.255.111.35&quot;]

class Solution &#123;    List&lt;String&gt; res = new ArrayList&lt;&gt;();    List&lt;String&gt; path = new ArrayList&lt;&gt;();    public List&lt;String&gt; restoreIpAddresses(String s) &#123;        dfs(0, s, 0);        return res;    &#125;    private void dfs(int i, String s, int cnt) &#123;//cnt用来记录生成的段数，只能是刚好四段整数才合法        int n = s.length();        if (i &gt; n) return;        if (i == n &amp;&amp; cnt == 4) &#123;//合法IP地址，加入答案            StringBuilder t = new StringBuilder();            for (String p : path) &#123;                t.append(p);                t.append(&quot;.&quot;);            &#125;            t.deleteCharAt(t.length() - 1);            res.add(t.toString());        &#125;        for (int j = 1; j &lt;= 3; ++ j) &#123;//为什么j从1到3？因为每一段整数的长度最长为3，最短为1            if (i + j &lt;= n) &#123;                String sub = s.substring(i, i + j);//以i为起点取长度为j的子串，然后判断这个子串合法与否，合法才加入path                if (validate(sub)) &#123;                    path.add(sub);                    dfs(i + j, s, cnt + 1);//递归到以i+j为起点，构造子串，同时生成的段数加一                    path.remove(path.size() - 1);                &#125;            &#125;        &#125;    &#125;    private boolean validate(String s) &#123;        if (s.length() &gt; 1 &amp;&amp; s.startsWith(&quot;0&quot;)) return false;        if (Integer.parseInt(s) &gt; 255) return false;        return true;    &#125;&#125;

113. 路径总和 II给你二叉树的根节点 root 和一个整数目标和 targetSum ，找出所有 从根节点到叶子节点 路径总和等于给定目标和的路径。
叶子节点 是指没有子节点的节点。
/** * Definition for a binary tree node. * public class TreeNode &#123; *     int val; *     TreeNode left; *     TreeNode right; *     TreeNode() &#123;&#125; *     TreeNode(int val) &#123; this.val = val; &#125; *     TreeNode(int val, TreeNode left, TreeNode right) &#123; *         this.val = val; *         this.left = left; *         this.right = right; *     &#125; * &#125; */class Solution &#123;    List&lt;List&lt;Integer&gt;&gt; res = new LinkedList&lt;&gt;();    List&lt;Integer&gt; path = new LinkedList&lt;&gt;();    public List&lt;List&lt;Integer&gt;&gt; pathSum(TreeNode root, int targetSum) &#123;        dfs(root, targetSum);        return res;    &#125;    private void dfs(TreeNode root, int tar) &#123;        if (root == null) return;        path.add(root.val);        tar -= root.val;        if (root.left == null &amp;&amp; root.right == null &amp;&amp; tar == 0) &#123;            res.add(new LinkedList&lt;&gt;(path));        &#125;        dfs(root.left, tar);        dfs(root.right, tar);        path.removeLast();        &#125;&#125;

784. 字母大小写全排列给定一个字符串 s ，通过将字符串 s 中的每个字母转变大小写，我们可以获得一个新的字符串。
