class Solution &#123;    List&lt;String&gt; ans = new ArrayList&lt;&gt;();    StringBuilder sb = new StringBuilder();    public List&lt;String&gt; letterCasePermutation(String s) &#123;        dfs(s, 0);        return ans;    &#125;    private void dfs(String s, int i) &#123;        if (i == s.length()) &#123;            ans.add(sb.toString());            return;        &#125;        char c = s.charAt(i);        sb.append(c);        dfs(s, i + 1);//先递归一次不管是数字还是字母        sb.deleteCharAt(sb.length() - 1);        if (Character.isLetter(c)) &#123;//再转换一次字母大小写            c ^= 32;//这个妙            sb.append(c);            dfs(s, i + 1);            sb.deleteCharAt(sb.length() - 1);        &#125;    &#125;&#125;

51. N 皇后原题去原链接看吧
class Solution &#123;    List&lt;List&lt;String&gt;&gt; ans;    boolean[] used;//记录第j列是否有皇后    boolean[] g1;//记录/方向上是否有皇后，这个方向满足性质r+c全部相等    boolean[] g2;//记录\方向上，这个方向满足性质r-c全部相等，但是有负数，所以注意    int[] col;//最重要的数组，存储第i行的皇后在第几列    public List&lt;List&lt;String&gt;&gt; solveNQueens(int n) &#123;        ans = new LinkedList&lt;&gt;();        used = new boolean[n];        g1 = new boolean[2 * n - 1];        g2 = new boolean[2 * n - 1];        col = new int[n];        dfs(0, n);        return ans;    &#125;    private void dfs(int r, int n) &#123;        if (r == n) &#123;//枚举完了所有行，构造答案            List&lt;String&gt; path = new LinkedList&lt;&gt;();            for (int i : col) &#123;                char[] c = new char[n];                Arrays.fill(c, &#x27;.&#x27;);                c[i] = &#x27;Q&#x27;;                path.add(new String(c));            &#125;            ans.add(path);            return;        &#125;        for (int j = 0; j &lt; n; ++ j) &#123; //枚举列            int t = r - j + n - 1;            if (!used[j] &amp;&amp; !g1[r + j] &amp;&amp; !g2[t]) &#123;                col[r] = j;                used[j] = g1[r + j] = g2[t] = true;                dfs(r + 1, n);                used[j] = g1[r + j] = g2[t] = false;            &#125;        &#125;    &#125;&#125;

