class Solution &#123;    List&lt;List&lt;Integer&gt;&gt; ans = new LinkedList&lt;&gt;();    List&lt;Integer&gt; path = new LinkedList&lt;&gt;();    int target;    public List&lt;List&lt;Integer&gt;&gt; combinationSum(int[] candidates, int target) &#123;        this.target = target;        dfs(0, candidates, 0);        return ans;    &#125;    private void dfs(int i, int[] candidates, int sum) &#123;        int n = candidates.length;        if (sum == target) &#123;            ans.add(new LinkedList&lt;&gt;(path));            return;        &#125;        for (int j = i; j &lt; n; ++ j) &#123;//枚举选哪个            if (sum + candidates[j] &lt;= target) &#123;                sum += candidates[j];                path.add(candidates[j]);                dfs(j, candidates, sum);                sum -= candidates[j];                path.removeLast();            &#125;        &#125;    &#125;&#125;

class Solution &#123;    List&lt;List&lt;Integer&gt;&gt; ans = new LinkedList&lt;&gt;();    List&lt;Integer&gt; path = new LinkedList&lt;&gt;();    int target;    public List&lt;List&lt;Integer&gt;&gt; combinationSum(int[] candidates, int target) &#123;        this.target = target;        dfs(0, candidates, 0);        return ans;    &#125;    private void dfs(int i, int[] candidates, int sum) &#123;        int n = candidates.length;        if (i == n) return;        if (sum == target) &#123;            ans.add(new LinkedList&lt;&gt;(path));            return;        &#125;        dfs(i + 1, candidates, sum);//选或者不选        if (sum + candidates[i] &lt;= target) &#123;            sum += candidates[i];            path.add(candidates[i]);            dfs(i, candidates, sum);            sum -= candidates[i];            path.removeLast();        &#125;    &#125;&#125;

