class Solution &#123;    List&lt;List&lt;Integer&gt;&gt; res = new LinkedList&lt;&gt;();    LinkedList&lt;Integer&gt; path = new LinkedList&lt;&gt;();    public List&lt;List&lt;Integer&gt;&gt; combinationSum2(int[] candidates, int target) &#123;        Arrays.sort(candidates);        //1 1 2 5 6 7 10        dfs(candidates, target, 0);        return res;    &#125;    private void dfs(int[] candidates, int t, int i) &#123;        if (t == 0) &#123;            res.add(new LinkedList&lt;&gt;(path));            return;        &#125;        for (int j = i; j &lt; candidates.length; ++ j) &#123;            if (j &gt; i &amp;&amp; candidates[j] == candidates[j - 1]) continue;            if (t &gt;= candidates[j]) &#123;                path.add(candidates[j]);                dfs(candidates, t - candidates[j], j + 1);                path.removeLast();            &#125;        &#125;    &#125;&#125;

