比如[[0,1], [2,0], [1,2]]，表示想上课程1就必须先上课程0，想上课程0就必须先上课程2，想上课程2就必须先上课程0，这就出现了循环依赖，也就是图中有环，死锁，返回false

DFS，为图建立邻接表

public class Solution &#123;    public boolean canFinish(int numCourses, int[][] prerequisites) &#123;        List&lt;List&lt;Integer&gt;&gt; graph = new ArrayList&lt;&gt;();        for (int i = 0; i &lt; numCourses; i++) &#123;            graph.add(new ArrayList&lt;&gt;());        &#125;        // 构建邻接表        for (int[] pre : prerequisites) &#123;            graph.get(pre[0]).add(pre[1]);        &#125;        // 状态数组，0：未访问，1：访问中，2：已访问        int[] status = new int[numCourses];        // 对每个节点进行 DFS        for (int i = 0; i &lt; numCourses; i++) &#123;            if (hasCycle(graph, status, i)) &#123;                return false; // 如果有环，返回 false            &#125;        &#125;        return true; // 如果无环，返回 true    &#125;    // DFS 检测是否有环    private boolean hasCycle(List&lt;List&lt;Integer&gt;&gt; graph, int[] status, int course) &#123;        if (status[course] == 1) &#123;            return true; // 发现环        &#125;        if (status[course] == 2) &#123;            return false; // 已经访问过，无环        &#125;        // 标记为访问中        status[course] = 1;        // 访问相邻节点        for (int nextCourse : graph.get(course)) &#123;            if (hasCycle(graph, status, nextCourse)) &#123;                return true; // 发现环            &#125;        &#125;        // 标记为已访问        status[course] = 2;        return false;    &#125;&#125;


拓扑排序

public class Solution &#123;    public static void main(String[] args) &#123;        int[][] prerequisites = new int[][]&#123;&#123;0, 1&#125;, &#123;1, 2&#125;, &#123;2, 0&#125;&#125;;        System.out.println(canFinish(3, prerequisites));    &#125;    public static boolean canFinish(int numCourses, int[][] prerequisites) &#123;        // 构建邻接表        List&lt;List&lt;Integer&gt;&gt; adjList = new ArrayList&lt;&gt;();        for (int i = 0; i &lt; numCourses; i++) &#123;            adjList.add(new ArrayList&lt;&gt;());        &#125;        // 构建入度表        int[] inDegree = new int[numCourses];        // 填充邻接表和入度表        for (int[] prereq : prerequisites) &#123;            int course = prereq[0];            int prereqCourse = prereq[1];            adjList.get(prereqCourse).add(course);  // 先修课程指向当前课程            inDegree[course]++;  // 当前课程的入度 +1        &#125;        // 初始化队列，加入所有入度为 0 的课程        Queue&lt;Integer&gt; queue = new LinkedList&lt;&gt;();        for (int i = 0; i &lt; numCourses; i++) &#123;            if (inDegree[i] == 0) &#123;                queue.offer(i);  // 入度为 0 的课程可以直接修            &#125;        &#125;        // 记录已处理课程的数量        int processedCourses = 0;        // 处理队列中的课程        while (!queue.isEmpty()) &#123;            int currCourse = queue.poll();  // 当前可以修的课程            processedCourses++;  // 已处理的课程数 +1            // 遍历当前课程的后继节点（依赖于当前课程的课程）            for (int nextCourse : adjList.get(currCourse)) &#123;                inDegree[nextCourse]--;  // 将后继课程的入度 -1                if (inDegree[nextCourse] == 0) &#123;                    queue.offer(nextCourse);  // 如果入度变为 0，加入队列                &#125;            &#125;        &#125;        // 如果处理的课程数量等于总课程数，说明无循环，返回 true        return processedCourses == numCourses;    &#125;&#125;

快速排序public static void main(String[] args) &#123;    int[] nums = &#123;5, 7, 3, 1, 9, 6, 4, 2, 8&#125;;    quick_sort(nums, 0, nums.length - 1);    for (int i = 0; i &lt; nums.length; i++) &#123;        System.out.print(nums[i] + &quot; &quot;);    &#125;&#125;private static void quick_sort(int[] nums, int low, int high) &#123;    if (high &lt;= low) &#123;        return;    &#125;    int pivot = nums[high];    int i = low;    for (int j = low; j &lt; high; j++) &#123;        if (nums[j] &lt; pivot) &#123;            swap(nums, i, j);            i ++;        &#125;    &#125;    swap(nums, i, high);    quick_sort(nums, low, i - 1);    quick_sort(nums, i + 1, high);&#125;public static void swap(int[] nums, int i, int j) &#123;    int temp = nums[i];    nums[i] = nums[j];    nums[j] = temp;&#125;

归并排序public static void main(String[] args) &#123;        int[] nums = &#123;5, 7, 3, 1, 9, 6, 4, 2, 8&#125;;        int[] t = new int[nums.length];        merge_sort(t, nums, 0, nums.length - 1);        for (int i = 0; i &lt; nums.length; i++) &#123;            System.out.print(nums[i] + &quot; &quot;);        &#125;    &#125;public static void merge_sort(int[] t, int[] nums, int left, int right) &#123;    if (left &gt;= right) &#123;        return;    &#125;    int mid = (left + right) / 2;    merge_sort(t, nums, left, mid);    merge_sort(t, nums, mid + 1, right);    int i = left, j = mid + 1, k = 0;    while (i &lt;= mid &amp;&amp; j &lt;= right) &#123;        if (nums[i] &lt;= nums[j]) &#123;            t[k ++] = nums[i ++];        &#125; else &#123;            t[k ++] = nums[j ++];        &#125;    &#125;    while (i &lt;= mid) &#123;        t[k ++] = nums[i ++];    &#125;    while (j &lt;= right) &#123;        t[k ++] = nums[j ++];    &#125;    for (k = 0, i = left; i &lt;= right;) &#123;        nums[i ++] = t[k ++];    &#125;&#125;

堆排序
建立大根堆，小根堆就改个小于号就行

public static void heapify(int[] nums, int cur) &#123;    int mx = cur, n = nums.length;    int l = 2 * cur + 1;//当前节点的左儿子    int r = 2 * cur + 2;    if (l &lt; n &amp;&amp; nums[l] &gt; nums[mx]) &#123;//如果左儿子比当前节点大        mx = l;//标记更大的    &#125;    if (r &lt; n &amp;&amp; nums[r] &gt; nums[mx]) &#123;        mx = r;    &#125;    if (mx != cur) &#123;//存在更大的        swap(nums, cur, mx);        heapify(nums, mx);//递归往下处理儿子节点    &#125;&#125;public static void swap(int[] nums, int i, int j) &#123;    int t = nums[i];    nums[i] = nums[j];    nums[j] = t;&#125;public static void main(String[] args) &#123;    int[] nums = new int[]&#123;5, 86, 12, 35, 53, 6, 10, 80, 99&#125;;    for (int i = nums.length / 2 - 1; i &gt;= 0; i--) &#123;//从第一个非叶子节点开始比较，也就是35        heapify(nums, i);    &#125;    Arrays.stream(nums).forEach(System.out::println);&#125;


加上排序：每次把堆顶与数组最后一个元素交换，然后数组长度 - 1，对前面的继续建堆，再交换。。。

public class Solution &#123;    public static void main(String[] args) &#123;        int[] nums = &#123;1, 2, 5, 9, 2, 3, 6, 8, 1&#125;;        hsort(nums, nums.length);        System.out.println(Arrays.toString(nums));    &#125;    private static void hsort(int[] nums, int len) &#123;        for (int i = len / 2 - 1; i &gt;= 0; i--) &#123;            heapify(nums, i, len);        &#125;        for (int i = len - 1; i &gt; 0; i--) &#123; //迭代排序            swap(nums, i, 0);  // 把堆顶元素(最大值)放到当前范围末尾            heapify(nums, 0, i);  // 堆的有效范围减少1，继续维护堆结构        &#125;    &#125;    private static void heapify(int[] nums, int cur, int len) &#123;        int left = cur * 2 + 1;        int right = cur * 2 + 2;        int largest = cur;        if (left &lt; len &amp;&amp; nums[left] &gt; nums[largest]) &#123;            largest = left;        &#125;        if (right &lt; len &amp;&amp; nums[right] &gt; nums[largest]) &#123;            largest = right;        &#125;        if (largest != cur) &#123;            swap(nums, cur, largest);            heapify(nums, largest, len);        &#125;    &#125;    private static void swap(int[] nums, int i, int j) &#123;        int temp = nums[i];        nums[i] = nums[j];        nums[j] = temp;    &#125;&#125;

public class Solution &#123;    public static void main(String[] args) &#123;        int[] nums = &#123;1, 2, 5, 9, 2, 3, 6, 8, 1&#125;;        hsort(nums, nums.length);        System.out.println(Arrays.toString(nums));    &#125;    private static void hsort(int[] nums, int len) &#123;        if (len &lt; 1) &#123;            return;        &#125;        for (int i = len / 2 - 1; i &gt;= 0; i--) &#123;            heapify(nums, i, len);        &#125;        swap(nums, len - 1, 0);  // 把堆顶元素(最大值)放到当前范围末尾        hsort(nums, len - 1);//递归排序    &#125;    private static void heapify(int[] nums, int cur, int len) &#123;        int left = cur * 2 + 1;        int right = cur * 2 + 2;        int largest = cur;        if (left &lt; len &amp;&amp; nums[left] &gt; nums[largest]) &#123;            largest = left;        &#125;        if (right &lt; len &amp;&amp; nums[right] &gt; nums[largest]) &#123;            largest = right;        &#125;        if (largest != cur) &#123;            swap(nums, cur, largest);            heapify(nums, largest, len);        &#125;    &#125;    private static void swap(int[] nums, int i, int j) &#123;        int temp = nums[i];        nums[i] = nums[j];        nums[j] = temp;    &#125;&#125;



计数排序思想就是将输入的数据值转化为键存储在额外开辟的数组空间中，要求输入的数据必须是有确定范围的整数，可以用数组每个元素减去数组中元素的最小值作为在额外数组的index，额外数组的长度就是max - min + 1
滑动子数组的美丽值，这道题用到了计数排序+滑动窗口
冒泡排序public static void bubbleSort(int[] nums) &#123;    for (int i = 0; i &lt; nums.length - 1; i++) &#123;        for (int j = i + 1; j &lt; nums.length; j++) &#123;            if (nums[i] &lt; nums[j]) &#123;                swap(nums, i, j);            &#125;        &#125;    &#125;&#125;

选择排序每次从待排序的数据元素中选出最小（或最大）的一个元素，存放在序列的起始位置
public static void chooseSort(int[] nums) &#123;    for (int i = 0; i &lt; nums.length; i++) &#123;        int t = i;        for (int j = i + 1; j &lt; nums.length; j++) &#123;            if (nums[j] &lt; nums[t]) &#123;                t = j;            &#125;        &#125;        swap(nums, i, t);    &#125;&#125;

插入排序前面是已排序序列，把后面未排序的数字依次插入到已排序序列的对应位置
public static void insertSort(int[] nums) &#123;    for (int i = 1; i &lt; nums.length; i++) &#123;        for (int j = i; j &gt; 0 &amp;&amp; nums[j] &lt; nums[j - 1]; j--) &#123;            swap(nums, j, j - 1);        &#125;    &#125;&#125;

拦截器介绍拦截器，顾名思义，是一个全局的拦截某些请求的东西，是AOP思想的具体实现，在Spring中Controller方法执行之前和之后都可以看到拦截器的身影。以下是一个web请求的执行流程


浏览器发送请求到Tomcat服务器
需要静态资源直接去项目目录访问，动态资源才进入后端代码
经过几个过滤器过滤
进入中央处理器寻找对应的Controller中的方法
配置的拦截器会动态拦截控制器（Controller）中方法的执行，在方法执行前后进行操作，如jwt校验鉴权

演示
自定义的拦截器需要实现HandlerInterceptor接口，接口中有三个方法preHandle、postHandle等等，都是默认方法，不必强制实现，所有接口的实现类都会通过继承得到这个方法。源码里默认返回true，意思是直接放行。

default boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler)        throws Exception &#123;    return true;&#125;



自定义拦截器：
@Componentpublic class TestInterceptor implements HandlerInterceptor &#123;    @Override    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception &#123;        System.out.println(&quot;preHandle&quot;);        System.out.println(request.getHeader(&quot;host&quot;)); // request：请求对象，这里输出localhost:8081        System.out.println(handler.getClass()); // handler：可以获取方法相关信息，这里输出        										//class org.springframework.web.method.HandlerMethod        HandlerMethod handlerMethod = (HandlerMethod) handler;        System.out.println(handlerMethod.getMethod().getName()); // 这里输出test        response.setStatus(999); //response: 响应对象，在preHandle里可以任意修改        return true; //如果为false则拦截方法和postHandle和afterCompletion都不执行    &#125;    //原始方法运行后运行，如果原始方法被拦截，则不执行    @Override    public void postHandle(HttpServletRequest request, HttpServletResponse response, Object handler, ModelAndView modelAndView) throws Exception &#123;        System.out.println(&quot;postHandle&quot;);        response.setStatus(888); // 修改失败，因为Controller方法执行结束后响应对象可能已经部分或完全提交    &#125;    //拦截器最后执行的方法，无论原始方法是否执行。用于清理资源    @Override    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) throws Exception &#123;        System.out.println(&quot;afterCompletion&quot;);        response.setStatus(777); // 修改失败，此时响应已经完成并提交给客户端。    &#125;&#125;


注册拦截器，配置要拦截的路径
@Configuration@Slf4jpublic class WebConfig implements WebMvcConfigurer &#123;    @Autowired    private TestInterceptor interceptor;    @Override    public void addInterceptors(InterceptorRegistry registry) &#123;        log.info(&quot;开始注册拦截器&quot;);        registry.addInterceptor(interceptor).addPathPatterns(&quot;/**&quot;).order(1);        //如果这里还有Interceptor2，配置了多个拦截器形成了拦截器链，那么执行流程是按照配置的顺序先进后出        //具体来说就是:preHandle1-&gt;preHandle2—&gt;拦截方法-&gt;postHandle2-&gt;posthandle1-&gt;afterCompletion2        // -&gt;afterCompletion1    &#125;&#125;


可以通过.order(1)来控制拦截器的执行优先级，数字越小优先级越高

