过滤器过滤器，是在java web中将你传入的request、response提前过滤掉一些信息，或者提前设置一些参数。然后再传入Servlet或Struts2的 action进行业务逻辑处理。比如过滤掉非法url（不是login.do的地址请求，如果用户没有登陆都过滤掉），或者在传入Servlet或Struts2的action前统一设置字符集，或者去除掉一些非法字符。
@Component @WebFilter(urlPatterns = &quot;/*&quot;) // 配置拦截路径public class TestFilter implements Filter &#123;    //只会随着服务器的启动初始化一次    @Override    public void init(FilterConfig filterConfig) throws ServletException &#123;        Filter.super.init(filterConfig);    &#125;    //每次请求都会被调用    @Override    public void doFilter(ServletRequest servletRequest, ServletResponse servletResponse, FilterChain filterChain) throws IOException, ServletException &#123;        HttpServletRequest request = (HttpServletRequest) servletRequest;        HttpServletResponse response = (HttpServletResponse) servletResponse;        System.out.println(&quot;过滤器拦截: &quot; + request.getRequestURI());        filterChain.doFilter(servletRequest, servletResponse);        System.out.println(&quot;要走了也得过滤一道。最终返回的状态码：&quot; + response.getStatus());    &#125;    @Override    public void destroy() &#123;        Filter.super.destroy();    &#125;&#125;

