public int[] pi(int n) &#123;    int []r = new int[n + 1];    for (int i = 2; i &lt;= n; ++ i) &#123;        if (r[i] == 0) &#123;            r[i] = r[i - 1] + 1;            for (int j = i * i; j &lt;= n; j += i) &#123;                r[j] = -1;            &#125;        &#125; else &#123;            r[i] = r[i - 1];        &#125;    &#125;    return r;&#125;//O(loglog(n))


