public int eura(int n) &#123;    boolean []is_prime = new boolean[n + 1];     Arrays.fill(is_prime, true);    List&lt;Integer&gt; primes = new ArrayList&lt;&gt;();//存储质数    for (int i = 2; i &lt;= n; ++ i) &#123;        if (is_prime[i]) &#123;            primes.add(i);        &#125;        for (int p : primes) &#123; //遍历质数列表            if (p * i &gt; n) break; //越界            is_prime[i * p] = false; //标记合数            if (i % p == 0) break; //只用到小于当前数i的最小因子的质数就退出        &#125;    &#125;    return primes.size();&#125;//O(n)

